<html>
<head>
  <style>
    body {
      margin: 0;
      padding: 15px;
      font-family: 'PingFang SC', 'Microsoft YaHei', sans-serif;
      background: linear-gradient(135deg, #FFE3E1, #FFF5E4);
      font-size: 14px;
    }

    .container {
      max-width: 700px;
      margin: 0 auto;
      background: rgba(255, 255, 255, 0.9);
      border-radius: 18px;
      padding: 20px;
      box-shadow: 0 8px 24px rgba(255, 209, 209, 0.25);
    }

    .header {
      display: flex;
      align-items: center;
      gap: 15px;
      margin-bottom: 20px;
    }

    .avatar {
      width: 100px;
      height: 100px;
      border-radius: 50%;
      border: 6px solid #FFD1D1;
      box-shadow: 0 4px 12px rgba(255, 148, 148, 0.3);
      object-fit: cover;
      transition: all 0.3s ease;
    }

    .avatar:hover {
      transform: scale(1.05);
      box-shadow: 0 6px 16px rgba(255, 148, 148, 0.4);
    }

    .title {
      flex: 1;
    }

    h1 {
      color: #FF9494;
      margin: 0 0 8px 0;
      font-size: 24px;
      letter-spacing: 1px;
      text-shadow: 1px 1px 2px rgba(255, 148, 148, 0.2);
    }

    .tags {
      display: flex;
      flex-wrap: wrap;
      gap: 6px;
      margin-bottom: 12px;
    }

    .tag {
      background: #DEEBFB;
      color: #666;
      padding: 3px 10px;
      border-radius: 12px;
      font-size: 12px;
      transition: all 0.2s ease;
      border: 1px solid transparent;
    }

    .tag:hover {
      background: #FFD1D1;
      color: #FF9494;
      border-color: #FFE3E1;
      transform: translateY(-2px);
    }

    .copyright {
      font-size: 12px;
      color: #666;
      padding: 10px;
      background: #FFE3E1;
      border-radius: 8px;
      margin-bottom: 15px;
      border: 1px dashed #FFD1D1;
    }

    .section {
      margin-bottom: 15px;
      background: rgba(255, 255, 255, 0.7);
      border-radius: 12px;
      padding: 12px;
      border: 1px solid #FFE3E1;
    }

    .section-title {
      color: #FF9494;
      font-size: 16px;
      margin-bottom: 8px;
      display: flex;
      align-items: center;
      font-weight: bold;
    }

    .section-title:before {
      content: '♡';
      margin-right: 8px;
      color: #FFD1D1;
      font-size: 18px;
    }

    .section-title:after {
      content: '♡';
      margin-left: 8px;
      color: #FFD1D1;
      font-size: 18px;
    }

    .content {
      color: #666;
      line-height: 1.5;
      font-size: 14px;
      background: rgba(255, 255, 255, 0.5);
      padding: 10px;
      border-radius: 8px;
    }

    .openings {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
      gap: 12px;
    }

    .opening {
      background: #FFF;
      padding: 12px;
      border-radius: 12px;
      border: 1px solid #FFD1D1;
      transition: all 0.3s ease;
      cursor: pointer;
      position: relative;
      overflow: hidden;
      box-shadow: 0 2px 8px rgba(255, 148, 148, 0.1);
    }

    .opening:before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      width: 4px;
      height: 100%;
      background: #FFD1D1;
      opacity: 0.5;
    }

    .opening:hover {
      background: #FFF5E4;
      transform: translateY(-3px);
      box-shadow: 0 5px 15px rgba(255, 148, 148, 0.2);
    }

    .opening:hover:before {
      opacity: 1;
    }

    @media (max-width: 600px) {
      .header {
        flex-direction: column;
        text-align: center;
      }

      .tags {
        justify-content: center;
      }

      body {
        padding: 10px;
        font-size: 13px;
      }

      .container {
        padding: 15px;
      }
    }
  </style>
</head>
